INSERT INTO repo_esd_objectives (esd_objective_id, domain, objective_no, text, status) VALUES ('ESD_SDG17_BEH_01', 'Behavioural', '1', 'The learner is able to become a change agent to realize the SDGs and to take on their role as an active, critical and global and sustainability citizen.', 'Active'), ('ESD_SDG17_BEH_02', 'Behavioural', '2', 'The learner is able to contribute to facilitating and implementing local, national and global partnerships for sustainable development.', 'Active'), ('ESD_SDG17_BEH_03', 'Behavioural', '3', 'The learner is able to publicly demand and support the development of policies promoting global partnerships for sustainable development.', 'Active'), ('ESD_SDG17_BEH_04', 'Behavioural', '4', 'The learner is able to support development cooperation activities.', 'Active'), ('ESD_SDG17_BEH_05', 'Behavioural', '5', 'The learner is able to influence companies to become part of global partnerships for sustainable development.', 'Active') ON CONFLICT DO NOTHING;